mapper.select:
select COUNT(*)::bigint

where t.due_date is not null
  and t.due_date::date < CURRENT_DATE
  and (t.status_detail is null or t.status_detail != 'Completed')
 and t.user_id = #{filterOwnerId}
${params.dataScope}

select COUNT(*)::bigint

where 1=1

 and l.org_id = #{filterOrgId}
 and l.user_id = #{filterOwnerId}
${params.dataScope}

select COUNT(*)::bigint

where l.convert_time is not null

 and l.org_id = #{filterOrgId}
 and l.user_id = #{filterOwnerId}
